import random
from boltons.cacheutils import LRU, LRI
PREV, NEXT, KEY, VALUE = 0,1,2,3

def check(c, tag):
    ll = {}
    link = c._anchor[NEXT]
    while link is not c._anchor:
        if link[KEY] is not None:   # sentinel has _MISSING not None
            pass
        ll[link[KEY]] = link[VALUE]
        link = link[NEXT]
    d = dict(c)
    assert ll == d, (tag, 'MISMATCH', ll, d)
    assert len(ll) <= c.max_size, (tag, len(ll), c.max_size)
    assert set(c._link_lookup) == set(d), (tag, set(c._link_lookup) ^ set(d))

for cls in (LRI, LRU):
    for seed in range(300):
        random.seed(seed)
        c = cls(max_size=random.randint(1,5))
        for i in range(60):
            k = random.choice('abcde')
            op = random.choice(['set','get','del','pop','setdefault','update','getitem'])
            try:
                if op=='set': c[k]=i
                elif op=='get': c.get(k)
                elif op=='getitem':
                    try: c[k]
                    except KeyError: pass
                elif op=='del':
                    try: del c[k]
                    except KeyError: pass
                elif op=='pop': c.pop(k, None)
                elif op=='setdefault': c.setdefault(k, i)
                elif op=='update': c.update({k:i})
            except Exception as e:
                print('ERR', cls.__name__, seed, op, type(e).__name__, e)
                raise
            check(c, (cls.__name__, seed, op, i))
print('consistency ok')
