import sys, pathlib, dis
sys.path.insert(0, 'work/repo')
import boltons.cacheutils as cu

# obtain module code object through gc of a function's closure? simplest: functions carry globals not module code.
# Instead re-walk from class code objects reachable via type objects
seen = {}
def walk(co, path):
    seen[path] = co
    for i, k in enumerate(co.co_consts):
        if isinstance(k, type(co)):
            walk(k, path + '/' + k.co_name)

for name in ('LRI', 'LRU'):
    walk(getattr(cu, name).__dict__['__init__'].__code__ if False else None, '') if False else None

# better: gather via each callable in module namespace
import types
for name, obj in vars(cu).items():
    if isinstance(obj, types.FunctionType):
        walk(obj.__code__, name)
    elif isinstance(obj, type):
        for mname, m in vars(obj).items():
            if isinstance(m, types.FunctionType):
                walk(m.__code__, name + '.' + mname)

src = pathlib.Path('work/repo/boltons/cacheutils.py').read_text().splitlines()
problems = []
for path, co in sorted(seen.items()):
    if not co.co_filename.endswith('cacheutils.py'):
        problems.append((path, 'wrong file', co.co_filename))
        continue
    # source line at firstlineno should be 'def' or 'class'
    ln = co.co_firstlineno
    s = src[ln-1] if 0 < ln <= len(src) else '<out of range>'
    if not (s.strip().startswith('def ') or s.strip().startswith('class ') or 'def ' in s):
        problems.append((path, ln, s))
print('anomalies:', len(problems))
for p in problems[:50]:
    print('  ', p)
print('total code objects scanned:', len(seen))
