from boltons.setutils import IndexedSet
import random
random.seed(31)
bad = 0

def oracle(s, L, tag):
    global bad
    if list(s) != L or len(s) != len(L): print('desync', tag); bad += 1; return False
    for a in range(-len(L)-3, len(L)+3):
        if not (-len(L) <= a < len(L)):
            try: s[a]; print('no raise', tag, a); bad += 1
            except IndexError: pass
        elif s[a] != L[a]: print('wrong get', tag, a); bad += 1; return False
    for st in [None,-5,-1,0,1,3,7]:
        for sp in [None,1,2,5,-1,-3]:
            for en in [None,-4,-1,0,2,6,9]:
                sl = slice(st, en, sp)
                if (sp is None or sp > 0):
                    if list(s[sl]) != L[sl]: print('fwd', tag, sl); bad += 1; return False
                elif list(s[sl]) != list(IndexedSet(s)[sl]):
                    print('neg', tag, sl); bad += 1; return False
    return True

# 1) hole-fill chains on big set
for gap in (1, 3, 7):
    L = list(range(400)); s = IndexedSet(L)
    # dead 100..119, live hole 120, dead 121..130 etc
    for base in range(100, 300, 40):
        for i in range(base, base+20):
            s.remove(i); L.remove(i)
        # live hole at base+25 then fill it after killing right side
        for i in range(base+26, base+30):
            s.remove(i); L.remove(i)
        s.remove(base+25); L.remove(base+25)
    oracle(s, L, f'holefill-{gap}')
    for _ in range(50):  # tail removals
        a = random.randrange(len(L))
        got = s.pop(a)
        if got != L.pop(a): print('pop wrong'); bad += 1; break
    oracle(s, L, f'holefill-{gap}-tail')

# 2) >384 distinct dead intervals -> _compact path
L = list(range(1200)); s = IndexedSet(L)
for i in range(0, 400, 3):   # ~134 separate intervals
    s.discard(i); 
    if i in L: L.remove(i)
oracle(s, L, 'manyint')
for i in range(401, 900, 2):
    s.discard(i)
    if i in L: L.remove(i)
oracle(s, L, 'manyint2')

# 3) pop(0)-heavy + reverse/sort interleaved
L = list(range(500)); s = IndexedSet(L)
for i in range(300):
    got = s.pop(random.choice([0, 0, 1, -1, len(L)//2]))
    if got != L.pop(L.index(got)): print('pop desync'); bad += 1; break
oracle(s, L, 'pop0')
s.reverse(); L.reverse(); oracle(s, L, 'reverse')
s.sort(); L.sort(); oracle(s, L, 'sort')
s.sort(key=lambda x: -x); L.sort(key=lambda x: -x); oracle(s, L, 'sortdesc')

# 4) dead > len/8 compaction threshold sweeps
for total, dead_every in [(64, 7), (128, 13), (1024, 100), (5000, 499)]:
    L = list(range(total)); s = IndexedSet(L)
    step = total // dead_every or 1
    for i in range(total - 1, -1, -step):
        s.discard(L[i]); 
        if L[i] in L: L.remove(L[i])
    oracle(s, L, f'cull-{total}')
