import random, itertools

def check(s, tag):
    live = list(s); fresh = IndexedSet(live)
    bad = []
    for start in list(range(-len(live)-3, len(live)+4)) + [None]:
        for stop in list(range(-len(live)-3, len(live)+4)) + [None]:
            for step in [None,1,2,3,4,-1,-2,-3]:
                sl = slice(start, stop, step)
                g = list(s[sl]) if True else None
                try: g = list(s[sl])
                except Exception as e: g = ('E', type(e).__name__)
                try: f = list(fresh[sl])
                except Exception as e: f = ('E', type(e).__name__)
                if g != f: bad.append(((start,stop,step), g, f))
    # index bounds with dead present
    idxb = []
    n = len(live)
    for idx in range(-n-4, n+4):
        try: g = s[idx]
        except IndexError: g='IOOR'
        except Exception as e: g='E:'+type(e).__name__
        try: e2 = live[idx]
        except IndexError: e2='IOOR'
        if g != e2: idxb.append((idx, g, e2))
    print(f'{tag}: slices_bad={len(bad)} idx_bad={len(idxb)}')
    for b in bad[:6]: print('   slice', b)
    for b in idxb[:8]: print('   idx', b)
    return len(bad)+len(idxb)

# scenario 1: report example
s = IndexedSet('abcdefghij'); s.remove('c')
check(s, 'report-remove-c')

