check(s, 'readd-c')

# scenario 3: pop end after removals
s = IndexedSet('abcdefghij'); s.remove('c'); s.remove('j'); s.pop()
check(s, 'remove-then-pop-end')

# scenario 4: heavy removals (compaction)
