def snap(d):
    """Full observable + internal-consistency snapshot; returns string or 'EXC:...'."""
    try:
        out = []
        out.append('len=%s' % len(d))
        try: out.append('keys=%r' % list(d))
        except Exception as e: out.append('keysEXC=%s:%s' % (type(e).__name__, e))
        try: out.append('keysin=%s' % ('k' in d))
        except Exception as e: out.append('keysinEXC=%s' % type(e).__name__)
        try: out.append('get=%r' % (d.get('k'),))
        except Exception as e: out.append('getEXC=%s:%s' % (type(e).__name__, e))
        try: out.append('getitem=%r' % (d['k'],))
        except Exception as e: out.append('getitemEXC=%s:%s' % (type(e).__name__, e))
        try: out.append('getlist=%r' % (d.getlist('k'),))
        except Exception as e: out.append('getlistEXC=%s' % type(e).__name__)
        try: out.append('repr=%s' % repr(d))
        except Exception as e: out.append('reprEXC=%s' % type(e).__name__)
        try: out.append('itemsM=%r' % d.items(multi=True))
        except Exception as e: out.append('itemsEXC=%s' % type(e).__name__)
        try: out.append('items1=%r' % d.items(multi=False))
        except Exception as e: out.append('items1EXC=%s' % type(e).__name__)
        try: out.append('rev=%r' % list(reversed(d)))
        except Exception as e: out.append('revEXC=%s' % type(e).__name__)
        # internal consistency: ll walk must match dict value lists
        try:
            m = getattr(d, '_map', None)
            if m is not None:
                cells = {k: len(v) for k, v in m.items()}
                out.append('map=%r' % cells)
                for k in d:
                    if d.__class__.__name__ != 'OneToOne':
                        vl = dict.get(d, k)
                        if not isinstance(vl, list):
                            out.append('BADVAL=%r' % (vl,))
                        elif cells.get(k) != len(vl):
                            out.append('MISMATCH %r cells=%s vals=%s' % (k, cells.get(k), len(vl)))
        except Exception as e:
            out.append('consistEXC=%s:%s' % (type(e).__name__, e))
        return ' '.join(out)
    except Exception as e:
        return 'SNAPFAIL %s:%s' % (type(e).__name__, e)

def run(cls, factory, pre):
    d = cls()
    if pre: d.add('k', 99)
    try:
        d.addlist('k', factory())
        err = None
    except Exception as e:
