import math

def naive(value, binary=False, gnu=False, fmt='%.1f'):
    # independent expectation: format in the unit where |reading| < base, then
    # bump the unit if the formatted number rounded up to >= base
    base = 1024 if (gnu or binary) else 1000
    if gnu: sfx = 'KMGTPEZYRQ'
    elif binary: sfx = ('KiB','MiB','GiB','TiB','PiB','EiB','ZiB','YiB','RiB','QiB')
    else: sfx = ('kB','MB','GB','TB','PB','EB','ZB','YB','RB','QB')
    a = abs(float(value))
    if a < base:
        return ('%dB' % int(value)) if gnu else ('%d Bytes' % int(value))
    exp = min(int(math.log(a, base)), len(sfx))
    while True:
        reading = fmt % (float(value)/base**exp)
        if exp < len(sfx) and abs(float(reading)) >= base:
            exp += 1
            continue
        return reading + ('' if gnu else ' ') + sfx[exp-1]

