    if x == 0: return Decimal(0)
    d = Decimal(x)
    exp = d.adjusted() - (p - 1)
    return d.scaleb(-exp).quantize(Decimal(1), rounding=ROUND_HALF_EVEN).scaleb(exp)

def parse(out, unit):
    s = out
    if unit:
        assert s.endswith(unit), out
        s = s[: -len(unit)]
    s = s.strip()
    for ch in s:
        if not (ch.isdigit() or ch in '.- '):
            return float(s.replace(' ','')), PREFIX[ch]
    return float(s.replace(' ','')), 0

def sigdigits(mstr):
