        mant, pe = parse(out, '')
        exp_val = float(round_sig(v, p))
        got_val = mant * 10**pe
        if exp_val != 0 and abs(got_val - exp_val) > abs(exp_val)*1e-12 or (exp_val==0 and got_val!=0):
