from more_itertools import numeric_range
# custom class where __rmul__ order matters: int*step vs step*int
class Num:
    def __init__(self,v): self.v=v
    def __add__(self,o): return Num(self.v+ (o.v if isinstance(o,Num) else o))
    def __radd__(self,o): return Num((o if isinstance(o,(int,float)) else o.v)+self.v)
    def __mul__(self,o): return Num(self.v*o)
    def __rmul__(self,o): return Num(o*self.v)
    def __sub__(self,o): return Num(self.v-(o.v if isinstance(o,Num) else o))
    def __neg__(self): return Num(-self.v)
    def __lt__(self,o): return self.v < (o.v if isinstance(o,Num) else o)
    def __le__(self,o): return self.v <= (o.v if isinstance(o,Num) else o)
    def __gt__(self,o): return self.v > (o.v if isinstance(o,Num) else o)
