// This is what `satisfies(version, range)` does, but for a simple range that
// has already been parsed.  The prerelease check has to be done against the
// whole set of comparators: `6.3.0-rc.5` is a member of
// `>=6.3.0-rc.4 <7.0.0-0`, even though it does not satisfy `<7.0.0-0` when
// that comparator is looked at in isolation.
const satisfiesSet = (version, set, options) => {
  for (const c of set) {
    if (!c.test(version)) {
      return false
    }
  }

  // only prereleases can be rejected here, and only when a comparator in
  // the set does not allow prereleases of the same [M.m.p] tuple.
  if (parseOptions(options).includePrerelease ||
      !version ||
      !version.prerelease ||
      !version.prerelease.length) {
    return true
  }

  for (const c of set) {
    if (c.semver !== ANY &&
        c.semver.prerelease.length &&
        c.semver.major === version.major &&
        c.semver.minor === version.minor &&
        c.semver.patch === version.patch) {
      return true
    }
  }

  return false
}

const minimumVersionWithPreRelease = [new Comparator('>=0.0.0-0')]"""
