const neu = require('./repo')
const origSubset = require('./orig/repo/ranges/subset.js')

// version universe spanning several tuples with many prerelease forms
const vers = []
for (const major of [0,1,2,3,6,7]) for (const minor of [0,1,3]) for (const patch of [0,1,2,4,5])
for (const pre of ['', '-0', '-a', '-b', '-rc.0', '-rc.4', '-rc.5', '-rc.6', '-z.1']) {
  vers.push(`${major}.${minor}.${patch}${pre}`)
}
vers.push('6.3.0-rc.10','6.3.0-rc.9','1.0.0-a.1','1.0.0-a.0')

const rnd = (n) => Math.floor(Math.random()*n)
const majors = [0,1,2,3,6]
const mkPre = () => { const r = rnd(6); return ['','-0','-a','-rc.0','-rc.4','-rc.5'][r] }
const mkCmp = () => {
  const op = ['','<','<=','>','>=','=','^','~'][rnd(8)]
  const M = majors[rnd(majors.length)], m = rnd(3), p = [0,1,2,4,5][rnd(5)]
  return `${op}${M}.${m}.${p}${mkPre()}`
}
const mkRange = () => {
  const r = rnd(4)
  if (r === 0) return mkCmp()
  if (r === 1) return `${mkCmp()} ${mkCmp()}`
  if (r === 2) return `${mkCmp()} ${mkCmp()} ${mkCmp()}`
  return `${mkCmp()} || ${mkCmp()}`
}

const contains = (a, b) => {
  for (const v of vers) if (neu.satisfies(v, a) && !neu.satisfies(v, b)) return [false, v]
  return [true, null]
}

let unsound = [], falseNeg = [], diffs = [], errs = 0
for (let i = 0; i < 20000; i++) {
  const a = mkRange(), b = mkRange()
  let o, n
  try { o = origSubset(a,b) } catch { o = 'ERR' }
  try { n = neu.subset(a,b) } catch { e='ERR'; n='ERR' }
  if (o === 'ERR' || n === 'ERR') { errs++; continue }
  if (o !== n && diffs.length < 50) diffs.push(`subset(${JSON.stringify(a)}, ${JSON.stringify(b)}): orig=${o} new=${n}`)
  const [cont, wit] = contains(a, b)
  if (cont && n !== true && falseNeg.length < 50) falseNeg.push(`subset(${a}, ${b}) = ${n} expected true (witness-containing check)`)
  if (!cont && n === true && unsound.length < 50) unsound.push(`subset(${a}, ${b}) = true expected false; witness ${wit}`)
}
console.log('errs(parse):', errs)
console.log('UNSOUND:', unsound.length); unsound.forEach(x=>console.log('  '+x))
console.log('FALSE NEG (sample):', falseNeg.length); falseNeg.slice(0,25).forEach(x=>console.log('  '+x))
console.log('DIFFS orig vs new (sample):', diffs.length); diffs.slice(0,25).forEach(x=>console.log('  '+x))
