const s = require('./')
const Comparator = require('./classes/comparator.js')

// dom membership per stated rule: all comparators must pass test, AND
// prerelease tuple rule applies across whole set.
function domMember(vStr, domSet, opts) {
  const v = new (require('./classes/semver.js'))(vStr, opts)
  let allPass = true
  for (const c of domSet) if (!c.test(v)) { allPass = false; break }
  if (!allPass) return false
  if (opts.includePrerelease || !v.prerelease.length) return true
  // prerelease: need some comparator same tuple with prerelease
  for (const c of domSet) {
    if (c.semver !== Comparator.ANY && c.semver.prerelease.length &&
        c.semver.major===v.major && c.semver.minor===v.minor && c.semver.patch===v.patch) return true
  }
  return false
}

// sub membership (same rule applied to sub set)
function subMember(vStr, subSet, opts) { return domMember(vStr, subSet, opts) }

// enumerate: build sub/dom as simple comparator sets directly from range strings
const Range = require('./classes/range.js')
const tuples = []
for (const M of [1]) for (const m of [0]) for (const p of [0,1,2,3]) tuples.push([M,m,p])
const versions = []
for (const [M,m,p] of tuples) for (const pre of ['','-0','-a','-b','-rc.4','-rc.5','-rc.6','-c']) versions.push(`${M}.${m}.${p}${pre}`)
versions.push('0.9.0','2.0.0','2.0.0-0')

function build(a,b){
  const A = new Range(a), B = new Range(b)
  for (const sSet of A.set) for (const dSet of B.set) {
    // members
    const subM = versions.filter(v=>subMember(v,sSet,{}))
    const domM = versions.filter(v=>domMember(v,dSet,{}))
    // containment: every sub member must be dom member, AND nonempty
    const contained = subM.length>0 && subM.every(v=>domM.includes(v))
    return {subM, domM, contained}
  }
}
// brute over pairs of simple ranges from atom lists, find where contained but new=false (regression)
