// The PRERELEASE regex is used in FULL (validation) and XRANGE (ranges) and COERCE.
// In FULL/XRANGE, the match must consume the ENTIRE string (anchored with $),
// so alternation order doesn't matter for correctness there - backtracking will
// explore all alternatives anyway since only one can succeed in consuming to $.
// 
// Let's confirm by testing: does reorder change any validation result?

const NUM = '0|[1-9]\\d*'
const NONNUM = '\\d*[a-zA-Z-][a-z-A-Z0-9-]*'.replace('z-A','z-za-A') // careful
// build correctly:
const NONNUM2 = '\\d*[a-zA-Z-][a-zA-Z0-9-]*'

function PI(order) {
  return order === 'orig'
    ? `(?:${NUM}|${NONNUM2})`
    : `(?:${NONNUM2}|${NUM})`
}
function PR(order) {
  return `(?:-(${PI(order)}(?:\\.${PI(order)})*))`
}
function FULL(order) {
  const MAIN = `((?:${NUM})\\.((?:${NUM})\\.((?:${NUM}))`
  // simpler manual:
  return `^v?(\\d+)\\.(\\d+)\\.(\\d+)${PR(order)}?(\\+[a-zA-Z0-9-.]+)?$`
}

