import re, itertools
import semver
from semver import Version

tokens = ["rc", "alpha", "beta", "a"]
prereleases = [
    "rc7","rc8","rc9","rc10","rc0","rc007","rc","rc.7","rc.10","rc7.1","rc7.9",
    "alpha3","beta2","rcx7","7rc","rc7beta","rc-beta7","rc7.beta","rc7.beta9",
    "rc1.2","rc2.0","rc.0","a1","a10","rc7rc8","rc7a","x7",
]
problems = []
for pre, tok in itertools.product(prereleases, tokens):
    v = Version.parse(f"2.4.0-{pre}")
    try:
        out = v.next_version("prerelease", tok)
    except Exception as e:
        problems.append((pre, tok, f"EXC {e}"))
        continue
    # style check: family result should keep no-dot style if input first seg had digits attached
    cur = v.prerelease.split(".")[0]
    fam = cur != tok and re.sub(r"\d+$", "", cur) == tok
    if fam:
        # expect increment of counter, style preserved (no token.N)
        if out.prerelease.startswith(tok + "."):
            problems.append((pre, tok, f"style reset -> {out}"))
        # monotonic in semver order?
        if not (out > v):
            problems.append((pre, tok, f"NOT GREATER: {v} -> {out}"))
    else:
        # mismatch or exact
        if cur == tok:
            if not (out > v):
                problems.append((pre, tok, f"exact NOT GREATER: {v} -> {out}"))
        else:
            exp = f"{tok}.1"
            if out.prerelease != exp and not (out > v):
                problems.append((pre, tok, f"reset odd: {v} -> {out}"))
for p in problems:
    print(p)
print("total flagged:", len(problems))
