"""Simulate the pre-fix old-style branch (raised counter returned unconditionally)."""
import re
from semver import Version

_orig = Version.next_version

def _patched(self, part, prerelease_token="rc"):
    if self.prerelease and prerelease_token and part == "prerelease":
        tok = str(prerelease_token)
        m = re.fullmatch(re.escape(tok) + r"(\d+)", self.prerelease)
        if m:
            return self.replace(prerelease=f"{tok}{int(m.group(1)) + 1}", build=None)
    return _orig(self, part, prerelease_token)

def pytest_configure(config):
    Version.next_version = _patched

def pytest_report_header(config):
    return "OLDSIM_BRANCH=active"
