import re
from semver import Version

_orig = Version.next_version

def _patched(self, part, prerelease_token="rc"):
    if self.prerelease and prerelease_token and part == "prerelease":
        tok = str(prerelease_token)
        Version._validate_identifiers(
            tok, Version._PRERELEASE_IDENTIFIER, "prerelease token"
